# Multi-agent pattern (conceptual)

class Agent:
    def __init__(self, name, role, tools=None):
        self.name = name
        self.role = role
        self.tools = tools or []
        self.memory = []

    def think(self, task):
        # Call LLM with role + task + memory
        return f'{self.name} thinking about: {task}'

    def act(self, thought):
        # Execute tool based on thought
        return f'{self.name} acting on: {thought}'

# Orchestrator-worker pattern
class Orchestrator(Agent):
    def __init__(self):
        super().__init__('Orchestrator', 'Break tasks into subtasks')
        self.workers = []

    def assign(self, task, worker):
        return worker.act(worker.think(task))

# Specialized workers
researcher = Agent('Researcher', 'Search and summarize')
coder = Agent('Coder', 'Write Python code')
reviewer = Agent('Reviewer', 'Review and fix code')

orchestrator = Orchestrator()
print(orchestrator.assign('Build a REST API', coder))
